    'linked',
    'Link eligible Scotiabank Scene+-earning credit card to Shell Go+ (Scene+ membership auto-links). Pay with the linked card at participating Shell stations.',
    '[{"kind":"cents_per_litre_instant","amount":3,"summary":"Instant 3¢/L off all fuel grades","appliesTo":"all_fuel","capLitresMonthly":1000},{"kind":"cents_per_litre_instant","amount":4,"summary":"Additional instant 4¢/L off Shell V-Power (promotional)","appliesTo":"shell_vpower","capLitresMonthly":1000,"promotional":true,"promotionalEnds":"2027-06-01"},{"kind":"points_per_litre","amount":1,"summary":"1 Scene+ point per litre on all fuel as a Scene+ member","appliesTo":"all_fuel","pointCurrency":"Scene+"},{"kind":"points_per_litre","amount":1,"summary":"Additional 1 Scene+ point per litre on V-Power as a Shell Go+ member (with linked Scene+ card)","appliesTo":"shell_vpower","pointCurrency":"Scene+"}]'::jsonb,
    true,
    'Up to 7¢/L instant (3+4 on V-Power) plus Scene+ points value (issuer cites up to ~3¢/L equivalent on V-Power when including card $ spend earn). National rollout May 26, 2026.',
    ARRAY['https://www.scotiabank.com/ca/en/personal/programs-services/shell.html', 'https://www.shell.ca/en_ca/drivers/loyalty-and-payment/partners/scotiabank.html']::text[],
    '2026-09-22'::date,
    now(),
    now(),
    'verified'::public.catalog_status
  ),
  (
    'shell-go-tangerine-scotia-cashback',
