    '[{"kind":"cents_per_litre_instant","amount":3,"summary":"Instant 3¢/L off all fuel grades","appliesTo":"all_fuel","capLitresMonthly":1000}]'::jsonb,
    true,
    'V-Power extra 4¢/L requires a Scene+-earning credit card. Cash-back cards still earn their own gas-category cash back.',
    ARRAY['https://www.scotiabank.com/ca/en/personal/programs-services/shell.html', 'https://www.tangerine.ca/en/about-us/press-releases/pr-2026-05-26']::text[],
    '2026-09-22'::date,
    now(),
    now(),
    'verified'::public.catalog_status
  ),
  (
    'journie-cibc-gas-discount',
    ARRAY['pioneer', 'ultramar', 'fas-gas', 'chevron-parkland', 'on-the-run']::text[],
    'journie',
    ARRAY['cibc-aeroplan-vi', 'cibc-dividend-vi', 'cibc-dividend', 'cibc-aventura-vi', 'cibc-aventura-gold', 'cibc-costco-mc', 'cibc-aeroplan-visa', 'cibc-dividend-vip', 'cibc-aventura-vip']::text[],
    'linked',
    'Register for JOURNIE, link eligible CIBC personal debit/credit card via CIBC Online/Mobile Banking, identify JOURNIE at pump (phone / app / card), and pay with the linked CIBC card. Simplii cards are excluded.',
    '[{"kind":"cents_per_litre_instant","amount":3,"summary":"Instant 3¢/L off any grade when JOURNIE is presented and linked CIBC card pays","appliesTo":"all_fuel","capLitresPerFill":100}]'::jsonb,
