    '[{"kind":"cents_per_litre_rewards","amount":5,"summary":"5¢/L back in CT Money on non-premium fuel with a Triangle credit card","appliesTo":"regular_fuel","pointCurrency":"Triangle"},{"kind":"cents_per_litre_rewards","amount":7,"summary":"7¢/L back in CT Money on premium fuel with a Triangle credit card","appliesTo":"premium_fuel","pointCurrency":"Triangle"},{"kind":"cents_per_litre_rewards","amount":3,"summary":"Up to 3¢/L in CT Money for Triangle Rewards members paying cash/debit (non-cardholder baseline)","appliesTo":"all_fuel_cash_debit","pointCurrency":"Triangle"}]'::jsonb,
